import { getAllPosts } from '@/lib/posts'
import { getAllEditions } from '@/lib/revisions'
import { getAllAtlasNodes, buildAtlasUrlPath } from '@/lib/atlas'
import { getGuide } from '@/lib/guide'

const BASE = 'https://vynr.app'

export function GET() {
  const posts = getAllPosts()
  const editions = getAllEditions()

  const staticUrls = [
    `<url><loc>${BASE}/</loc></url>`,
    `<url><loc>${BASE}/blog</loc></url>`,
    ...posts.map(
      p => `<url><loc>${BASE}/blog/${p.slug}</loc></url>`
    ),
    `<url><loc>${BASE}/revisions</loc></url>`,
    ...editions.map(
      e => `<url><loc>${BASE}/revisions/${e.editionId}</loc></url>`
    ),
    `<url><loc>${BASE}/about</loc></url>`,
    `<url><loc>${BASE}/guide</loc></url>`,
    ...getGuide().chapters.map(
      c => `<url><loc>${BASE}/guide/${c.id}</loc></url>`
    ),
    `<url><loc>${BASE}/roadmap</loc></url>`,
    `<url><loc>${BASE}/vynr-plus</loc></url>`,
    `<url><loc>${BASE}/privacy</loc></url>`,
    `<url><loc>${BASE}/support</loc></url>`,
    `<url><loc>${BASE}/contact</loc></url>`,
    `<url><loc>${BASE}/terms</loc></url>`,
  ]

  const atlasUrls = [
    `<url><loc>${BASE}/atlas</loc></url>`,
    ...getAllAtlasNodes()
      .filter(n => n.level !== 'root')
      .map(n => `<url><loc>${BASE}${buildAtlasUrlPath(n)}</loc></url>`),
  ]

  const body = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${[...staticUrls, ...atlasUrls].join('\n')}
</urlset>`

  return new Response(body, {
    headers: { 'Content-Type': 'application/xml' },
  })
}
export function GET() {
  return new Response(
    `User-agent: *
Allow: /
Sitemap: https://vynr.app/sitemap.xml`,
    {
      headers: {
        'Content-Type': 'text/plain',
      },
    }
  )
}

